# ---------- Тексерістер ----------
strip = lambda e: re.sub(r"\s*\([^)]*(азатжол|бөлім)[^)]*\)$", "", e)
errs = 0
for x in Q:
    assert x["key"] in "ABCD" and len(x["options"]) == 4
    assert set(x["distractor_notes"]) == set("ABCD") - {x["key"]}, x["id"]
    body = " ".join(next(t for t in texts if t["id"] == x["text_id"])["paragraphs"]).replace("**", "")
    groups = [("ok", x["evidence"])] + [(k, v) for k, v in x["distractor_evidence"].items() if v]
    for k, evs in groups:
        for e in evs:
            for frag in [f.strip(" .") for f in strip(e).split("...")]:
                if frag and frag not in body: print("ДӘЛЕЛ ТАБЫЛМАДЫ:", x["id"], "|", frag); errs += 1
        kk_all = " ".join(strip(e) for e in evs)
        for w in x["keywords"].get(k, {"kk": []})["kk"]:
            if w.lower() not in kk_all.lower(): print("КІЛТ СӨЗ ЖОҚ:", x["id"], k, "|", w); errs += 1
assert [x["number"] for x in Q] == list(range(1, 21))
assert not errs, errs

